INSERT INTO departments (id, slug, name, short_description, full_description, mission, vision, values, objectives, established_date, logo_key, cover_image_key, cover_image, accent_color, stats, programs, telegram_link, telegram_chat_id, registration_status, registration_fields, requirements)
VALUES ('dept-school', 'school', '{"ar":"مدرسة دار القرآن الكريم لخديجة بنت خويلد","en":"Dar Al-Quran School for Khadija bint Khuwaylid","am":"ዳር አል-ቁርአን ትምህርት ቤት ለኻዲጃ ብንት ኽወይሊድ","om":"Barumsa Daar Al-Quraan Khadiija binti Khuwaylid"}', '{"ar":"مدرسة متكاملة لتعليم القرآن والعلوم الشرعية من المرحلة التمهيدية حتى الصف الخامس","en":"A comprehensive school teaching Quran and Islamic sciences from preparatory to Grade 5","am":"ከቅድመ-ደረጃ እስከ 5ኛ ክፍል ቁርአንን እና የእስላም ሳይንሶችን የሚያስተምር ሙሉ ትምህርት ቤት","om":"Kutaalee qophaa''ii hanga kutaa shanaffaa Quraana fi saayinsii Islaamaa barsiisu"}', '{"ar":"تأسست المدرسة عام 1438هـ (2009 بالتقويم الإثيوبي) كأول أقسام المؤسسة. تقدم المدرسة منهجاً متدرجاً يبدأ من مرحلة التمهيد (قاعدة النورانية ثم قراءة القرآن) ثم التسجيل، ويمتد إلى الصفوف من الأول إلى الخامس. يدرس في المدرسة أكثر من 642 طالباً وطالبة سنوياً بأكثر من 10 معلمين مؤهلين. تجدر الإشارة إلى أن رئيس هيئة التدريس ورئيس اتحاد الطلاب وفريق القيادة جميعهم من خريجي هذه المدرسة.","en":"The school was established in 1438H (2009 Ethiopian calendar) as the first department of the institution. It offers a progressive curriculum starting from the preparatory stage (Qaida Nuraniyyah then Quran reading) then certification, extending to Grades 1 through 5. Over 642 students study annually with more than 10 qualified teachers. Notably, the chairperson of teachers, student union head, and leadership team are all alumni of this school.","am":"ትምህርት ቤቱ በ1438ሂ (2009 የኢትዮጵያ ቀን መቁጠሪያ) እንደ መጀመሪያ ክፍል ተመሰረተ። ከቅድመ-ደረጃ እስከ 5ኛ ክፍል ድረስ ቀጣይ ማስተማር ይሰጣል። በየዓመቱ ከ642 በላይ ተማሪዎች ይማራሉ።","om":"Barumsi kun 1438H (2009 kabajaa Itoophiyaa) kan hundeeffame. Piroogiraamii itti fufiinsa qabu qophaa''ee hanga kutaa shanaffaa kenna. Barattoota 642 ol waggaa tokkotti baratan."}', '{"ar":"تعليم كتاب الله والعلوم الشرعية لأبناء وبنات المسلمين على منهج متدرج ومتكامل","en":"Teaching the Book of Allah and Islamic sciences to Muslim children through a progressive and integrated curriculum","am":"ለሙስሊም ልጆች ቁርአንን እና የእስላም ሳይንሶችን በቀጣይ ማስተማር","om":"Ilmaan Muslimootaaf Quraana fi saayinsii Islaamaa itti fufiinsa qabuun barsiisuu"}', '{"ar":"جيل قُرآني متشبّع بالقيم والأخلاق، حافظ لكتاب الله، عالم بدينه","en":"A Quranic generation imbued with values and morals, preserving the Book of Allah, knowledgeable of their religion","am":"በእሴቶች እና በምግባር የተሞላ፣ ቁርአንን የሚያስታውስ፣ ሃይማኖቱን የሚያውቅ ትውልድ","om":"Dhaloota Quraanaa gadaa fi gaarii, Quraana hafzee amantaa isaa beeku"}', '[{"ar":"التجويد المضبوط","en":"Proper Tajwid","am":"ትክክለኛ ተጅዊድ","om":"Tajwiida sirrii"},{"ar":"التربية الإسلامية","en":"Islamic upbringing","am":"የእስላማዊ ትምህርት","om":"Kan Islaamaa guddisuu"},{"ar":"الإتقان التدريجي","en":"Progressive mastery","am":"ቀጣይ ማስተማር","om":"Itti fufiinsa qabu sirrii"},{"ar":"الانضباط والأخلاق","en":"Discipline and morals","am":"ልማድ እና ምግባር","om":"Sangaa fi gaarii"}]', '[{"ar":"تعليم قراءة القرآن بالتجويد","en":"Teach Quran reading with Tajwid","am":"ቁርአንን በተጅዊድ ማስተማር","om":"Quraana Tajwiidaan barsiisuu"},{"ar":"تأسيس طلاب في العلوم الشرعية","en":"Establish students in Islamic sciences","am":"ተማሪዎችን በእስላም ሳይንስ ማስተማር","om":"Barattoota saayinsii Islaamaa keessaa haa qopheessuu"},{"ar":"إعداد جيل حافظ لكتاب الله","en":"Prepare a generation that preserves the Book of Allah","am":"ቁርአንን ለሚያስታውስ ትውልድ ማሰልጠን","om":"Dhaloota Quraana hafzuu qopheessuu"}]', '1438 هـ (2009 م.أ)', 'school', 'school', 'https://images.pexels.com/photos/22686432/pexels-photo-22686432.jpeg?auto=compress&cs=tinysrgb&w=1600', '{"base":"#15803d","accent":"#BF8414"}', '[{"label":{"ar":"طالب سنوياً","en":"Students yearly","am":"የዓመት ተማሪ","om":"Barattoota waggaa"},"value":642},{"label":{"ar":"معلم مؤهل","en":"Qualified teachers","am":"ብቁ መምህር","om":"Barsiisota qopheessitoo"},"value":10},{"label":{"ar":"صفوف دراسية","en":"Grade levels","am":"የክፍል ደረጃዎች","om":"Safii barumsaa"},"value":5}]', '[{"name":{"ar":"قاعدة نورانية","en":"Qaidetunuraniya","am":"ቃዒደ ኑራኒያ","om":"Qaida Nuraaniyyaa"},"gradeGroup":"temhid-1","icon":"alphabet","description":{"ar":"اللبنة الأولى: تعلم الحروف وأصواتها ومخارجها بقاعدة نورانية مبسطة تهيئ الطفل لقراءة القرآن.","en":"The first building block: learning letters, their sounds, and articulation points through a simplified Nuraniyyah primer that prepares the child to read the Quran.","am":"የመጀመሪያው ድንጋይ፡ ፊደላትን፣ ድምጾቻቸውን እና የድምፅ መውጫቦችን በቀላል የኑራኒያ መግቢያ ተማሮ ልጁ ቁርአንን ለማንበብ ይዘጋጅ።","om":"Iddoo jalqabaa: qubeelee, sagalee isaanii fi baay''i isaanii Qaida Nuraaniyyaa salphaadhaan barachuu, ilmaan Quraana dubbisuuf qopheessuu."}},{"name":{"ar":"الأناشيد","en":"Anashids","am":"አናሺድ","om":"Anaashiid"},"gradeGroup":"temhid-1","icon":"music","description":{"ar":"أناشيد تربوية هادفة تعلّم القيم والأخلاق بنغمات يحفظها الطفل ويرددها بفرح.","en":"Purposeful educational chants that teach values and morals through melodies the child memorizes and joyfully repeats.","am":"እሴቶችንና ምግባርን በሚያስተምሩ ዘፈኖች የልጁ የሚያስታውስና በደስታ የሚደግም የስነ-ጥበብ ስልጠና።","om":"Gorsa gaarii fi qabxii qabu barsiisu, ilmaan akka hafuufi gammadoo ta''uun deebi''u."}},{"name":{"ar":"القرآن","en":"Quran","am":"ቁርአን","om":"Quraana"},"gradeGroup":"temhid-2","icon":"bookOpen","description":{"ar":"انتقال سلس من الحروف إلى الكلمات والآيات، حتى يقرأ الطفل القرآن قراءة صحيحة مرتّلة.","en":"A smooth transition from letters to words and verses, until the child reads the Quran correctly and in a measured tone.","am":"ከፊደላት ወደ ቃላትና አንቀጾች ለስለስ ያለ ሽግግር፣ ልጁ ቁርአንን በትክክል እና በመጠነኛ ድምፅ አነብ ዘንድ።","om":"Qubeelee irraa jechoota fi keeyyataatti siroomsaa, ilmaan Quraana sirrii ta''een akka dubbisu."}},{"name":{"ar":"الأناشيد","en":"Anashids","am":"አናሺድ","om":"Anaashiid"},"gradeGroup":"temhid-2","icon":"music","description":{"ar":"أناشيد تربوية هادفة تعلّم القيم والأخلاق بنغمات يحفظها الطفل ويرددها بفرح.","en":"Purposeful educational chants that teach values and morals through melodies the child memorizes and joyfully repeats.","am":"እሴቶችንና ምግባርን በሚያስተምሩ ዘፈኖች የልጁ የሚያስታውስና በደስታ የሚደግም የስነ-ጥበብ ስልጠና።","om":"Gorsa gaarii fi qabxii qabu barsiisu, ilmaan akka hafuufi gammadoo ta''uun deebi''u."}},{"name":{"ar":"القرآن الكريم","en":"Qur''an","am":"ቅዱስ ቁርአን","om":"Quraana Quulqulluu"},"gradeGroup":"grade-1","icon":"book","description":{"ar":"حفظ سور قصيرة وتجويد الدرس، مع ترسيخ الحب لكتاب الله في قلوب الصغار.","en":"Memorizing short surahs and reciting the lesson with tajwid, while anchoring love for the Book of Allah in young hearts.","am":"አጭር ሱራዎችን ማስታወስ እና ትምህርቱን በተጅዊድ አንበብ፣ በታናሾች ልቦች ለመጽሐፈ አላህ ፍቅርን ማትረው።","om":"Suura gabaabaa hafzee fi tajwiidaan dubbisuu, onnee ilmaan xixiqqoo keessatti jaalala Kitaaba Rabbii cimsuu."}},{"name":{"ar":"التوحيد","en":"Tawhid","am":"ተውሂድ","om":"Tawhiid"},"gradeGroup":"grade-1","icon":"gem","description":{"ar":"تعريف الصغير بربه وأسمائه الحسنى، بأسلوب مبسط يرسخ عقيدة التوحيد.","en":"Introducing the young child to their Lord and His beautiful names, in a simple way that anchors the creed of Tawhid.","am":"ታናሹን ከጌታው እና ከቆንጆ ስሞቹ ጋር በማስተዋወቅ፣ የተውሂድን እምነት የሚያረጋግጥ ቀላል መንገድ።","om":"Ilma xiqqaa Gooftaa isaa fi maqaa bareedaa Isaa meettu, akkasuma amantaa Tawhiida cimsuu."}},{"name":{"ar":"التجويد","en":"Tejwid","am":"ተጅዊድ","om":"Tajwiid"},"gradeGroup":"grade-1","icon":"mic","description":{"ar":"إتقان مخارج الحروف وأحكام النون الساكنة والمدود، لقراءة سليمة خالية من اللحن.","en":"Mastering letter articulation points, the rules of the silent noon, and elongations — for a sound, error-free recitation.","am":"የፊደል መውጫቦችን፣ የፀጥታ ኑን ህጎችን እና የማራዘሚያ ምልክቶችን መውደቅ — ለንፁሕ እና ለነፃ ንባብ።","om":"Baay''i qubeelee, seera noonii haaquu fi diriirsuu qabachuu — dubbisaa sirrii dogoggoraa hin qabne."}},{"name":{"ar":"الفقه","en":"Fiqh","am":"ፊቅህ","om":"Fiqh"},"gradeGroup":"grade-1","icon":"scale","description":{"ar":"أحكام الطهارة والصلاة بأسلوب عملي يربط الطفل بعباداته اليومية.","en":"Rulings of purification and prayer in a practical style that connects the child to their daily acts of worship.","am":"የንጽህናና የሰላት ህጎችን በተግባራዊ መንገድ፣ ልጁን ከእለት አምልኮው ጋር የሚያገናኝ።","om":"Seera qulqullinaa fi duulaa karaa hojiirra, ilmaan waliin galgala guyyaa isaanii walitti qabuu."}},{"name":{"ar":"اللغة","en":"Lugha","am":"ቋንቋ","om":"Afaan"},"gradeGroup":"grade-1","icon":"languages","description":{"ar":"بناء اللسان العربي ومفرداته، ليُعين الطالب على فهم القرآن والعلوم الشرعية.","en":"Building Arabic language fluency and vocabulary, to help the student understand the Quran and Islamic sciences.","am":"የዐረብኛ ቋንቋንና የቃላት ክምችት መገንባት፣ ተማሪው ቁርአንንና የእስላም ሳይንሶችን ለመረዳት።","om":"Afaan Arabaa fi jechoota isaa ijaruu, barataan Quraana fi saayinsii Islaamaa akka hubatu gargaaruu."}},{"name":{"ar":"القرآن الكريم","en":"Qur''an","am":"ቅዱስ ቁርአን","om":"Quraana Quulqulluu"},"gradeGroup":"grade-2","icon":"book","description":{"ar":"حفظ سور قصيرة وتجويد الدرس، مع ترسيخ الحب لكتاب الله في قلوب الصغار.","en":"Memorizing short surahs and reciting the lesson with tajwid, while anchoring love for the Book of Allah in young hearts.","am":"አጭር ሱራዎችን ማስታወስ እና ትምህርቱን በተጅዊድ አንበብ፣ በታናሾች ልቦች ለመጽሐፈ አላህ ፍቅርን ማትረው።","om":"Suura gabaabaa hafzee fi tajwiidaan dubbisuu, onnee ilmaan xixiqqoo keessatti jaalala Kitaaba Rabbii cimsuu."}},{"name":{"ar":"التوحيد","en":"Tawhid","am":"ተውሂድ","om":"Tawhiid"},"gradeGroup":"grade-2","icon":"gem","description":{"ar":"تعريف الصغير بربه وأسمائه الحسنى، بأسلوب مبسط يرسخ عقيدة التوحيد.","en":"Introducing the young child to their Lord and His beautiful names, in a simple way that anchors the creed of Tawhid.","am":"ታናሹን ከጌታው እና ከቆንጆ ስሞቹ ጋር በማስተዋወቅ፣ የተውሂድን እምነት የሚያረጋግጥ ቀላል መንገድ።","om":"Ilma xiqqaa Gooftaa isaa fi maqaa bareedaa Isaa meettu, akkasuma amantaa Tawhiida cimsuu."}},{"name":{"ar":"التجويد","en":"Tejwid","am":"ተጅዊድ","om":"Tajwiid"},"gradeGroup":"grade-2","icon":"mic","description":{"ar":"إتقان مخارج الحروف وأحكام النون الساكنة والمدود، لقراءة سليمة خالية من اللحن.","en":"Mastering letter articulation points, the rules of the silent noon, and elongations — for a sound, error-free recitation.","am":"የፊደል መውጫቦችን፣ የፀጥታ ኑን ህጎችን እና የማራዘሚያ ምልክቶችን መውደቅ — ለንፁሕ እና ለነፃ ንባብ።","om":"Baay''i qubeelee, seera noonii haaquu fi diriirsuu qabachuu — dub